import { Question } from '@/types/question';

const questions: Question[] = [
  { id: 'ai-engineer-vector-db-l4-001', language: 'ai-engineer', level: 'level4', category: 'Vector Databases & Embeddings', subcategory: 'Index Structures', question: 'What is the IVF-PQ (Inverted File with Product Quantization) index and what are its recall-speed trade-offs?', options: ['IVF-PQ always achieves 100% recall', 'PQ increases memory usage compared to storing raw vectors', 'IVF-PQ stores all vectors uncompressed', 'IVF partitions vectors into Voronoi cells using k-means centroids. PQ compresses each vector into short codes by splitting dimensions into subspaces and quantizing each independently. At query time, only nprobe cells are searched using precomputed distance tables. This trades recall (missing vectors in unsearched cells) for speed (100x faster than brute force) and memory (32x compression with PQ)'], correctAnswer: 3, explanation: 'IVF-PQ (Jégou et al. 2011): (1) IVF: cluster N vectors into K centroids via k-means. At query time, compute distance to all K centroids, search only nprobe nearest cells (~1-10% of cells). (2) PQ: split 768-d vector into 96 subspaces of 8 dims each, quantize each subspace to 256 centroids (1 byte per subspace) → 96 bytes per vector instead of 3072 bytes (32x compression). Distance computed via precomputed lookup tables (ADC). Trade-offs: nprobe↑ = better recall, slower. PQ nbits↑ = better recall, more memory. Typical: 95% recall@10 with 10ms search on 1B vectors.', tags: ['ivf-pq', 'product-quantization', 'ann-search', 'index-structure'] },
  { id: 'ai-engineer-vector-db-l4-002', language: 'ai-engineer', level: 'level4', category: 'Vector Databases & Embeddings', subcategory: 'HNSW', question: 'How does the HNSW (Hierarchical Navigable Small World) graph achieve efficient ANN search?', options: ['HNSW is a tree-based index structure', 'HNSW builds a multi-layer graph where each layer is a navigable small-world graph with decreasing density. Search starts at the top layer (sparse, long-range connections for coarse navigation), then descends to denser layers for fine-grained search. At each layer, greedy search follows edges to neighbors closer to the query. The hierarchical structure provides O(log N) search complexity with high recall and no quantization loss', 'HNSW uses the same search algorithm as k-d trees', 'HNSW requires reindexing when new vectors are added'], correctAnswer: 1, explanation: 'HNSW (Malkov & Yashunin 2018): construction assigns each vector to layers 0..l where l is drawn exponentially (most vectors only in layer 0). Connections: each node connects to M nearest neighbors in each layer. Search: enter at top layer → greedy descent through layers → beam search in layer 0. Key parameters: M (connections per node, higher = better recall, more memory), ef_construction (beam width during build), ef_search (beam width during query). Properties: O(log N) expected search time, no compression (exact distances), supports incremental inserts. Downsides: high memory (store graph + raw vectors), slow index build. Used in: Pinecone, Weaviate, Qdrant, pgvector.', tags: ['hnsw', 'graph-index', 'navigable-small-world', 'ann-search'] },
  { id: 'ai-engineer-vector-db-l4-003', language: 'ai-engineer', level: 'level4', category: 'Vector Databases & Embeddings', subcategory: 'Hybrid Search', question: 'What is hybrid search combining dense and sparse retrieval, and how are scores fused?', options: ['Hybrid search runs both dense (embedding-based) and sparse (BM25/keyword-based) retrieval in parallel, then fuses results. Score fusion methods: Reciprocal Rank Fusion (RRF) combines rankings without needing score calibration, weighted linear combination requires normalized scores, and cross-encoder reranking provides the best quality by scoring each candidate with a transformer. Hybrid outperforms either alone because dense captures semantics while sparse handles exact keyword matching', 'Sparse retrieval always outperforms dense retrieval', 'Score fusion requires training a separate ML model', 'Hybrid search uses only dense embeddings'], correctAnswer: 0, explanation: 'Dense retrieval: embed(query) · embed(doc) captures semantic similarity ("car" matches "automobile") but misses exact terms. Sparse (BM25): tf-idf matching captures exact keywords but misses paraphrases. Hybrid: run both → fuse. RRF: score(d) = Σ 1/(k + rank_i(d)) — simple, no score normalization needed, works well empirically. Linear: α·dense_score + (1-α)·sparse_score, requires calibrated scores. Cross-encoder reranking: encode (query, doc) pair → relevance score. Most production RAG systems use hybrid retrieval with cross-encoder reranking for best results. Vespa, Weaviate, and Elasticsearch support hybrid natively.', tags: ['hybrid-search', 'rrf', 'dense-sparse', 'score-fusion'] },
  { id: 'ai-engineer-vector-db-l4-004', language: 'ai-engineer', level: 'level4', category: 'Vector Databases & Embeddings', subcategory: 'Embedding Training', question: 'What is the InfoNCE contrastive loss used for training embedding models and what is the role of temperature?', options: ['InfoNCE (Normalized Temperature-scaled Cross Entropy) treats the problem as (N+1)-way classification: given a query, identify the positive out of 1 positive + N negatives. L = -log(exp(sim(q,k+)/τ) / Σ exp(sim(q,ki)/τ)). Temperature τ controls the sharpness of the distribution: lower τ makes the loss focus more on hard negatives, higher τ creates a softer distribution. Larger batch sizes provide more in-batch negatives, improving embedding quality', 'InfoNCE requires labeled data with explicit relevance scores', 'Temperature has no effect on the loss function', 'InfoNCE uses mean squared error between embeddings'], correctAnswer: 0, explanation: 'InfoNCE (van den Oord et al. 2018): L = -log(exp(s+/τ) / (exp(s+/τ) + Σ exp(s-/τ))) where s+ = sim(q, positive), s- = sim(q, negative). Low τ (0.01-0.05): gradients dominated by hardest negatives (most similar to query), sharper decision boundary but can overfit to hard negatives. High τ (0.1-1.0): gentler gradients, considers all negatives equally. Batch size matters: B=4096 provides 4095 in-batch negatives per query. CLIP uses τ as a learnable parameter initialized at 0.07. Cross-batch negatives (MoCo\'s memory bank) provide even more negatives without increasing batch size.', tags: ['infonce', 'contrastive-loss', 'temperature', 'embedding-training'] },
  { id: 'ai-engineer-vector-db-l4-005', language: 'ai-engineer', level: 'level4', category: 'Vector Databases & Embeddings', subcategory: 'Quantization', question: 'What is scalar quantization versus product quantization for vector compression, and when should each be used?', options: ['Scalar quantization cannot be applied to embedding vectors', 'Scalar quantization independently quantizes each dimension (e.g., float32 → int8 per dimension), achieving 4x compression with minimal recall loss. Product quantization groups dimensions into subspaces and learns codebooks per subspace, achieving 32-96x compression but with more recall loss and slower encoding. Use scalar for moderate compression with high recall; use PQ when memory is extremely constrained (billions of vectors)', 'Scalar and product quantization are identical', 'Product quantization always has better recall than scalar quantization'], correctAnswer: 1, explanation: 'Scalar quantization (SQ): map each float32 dimension to int8 using min-max scaling. 768-d vector: 3072 bytes → 768 bytes (4x). Very fast encoding/decoding, <1% recall loss at int8. Product quantization (PQ): divide 768-d into 96 groups of 8-d, learn 256 centroids per group. Each vector → 96 bytes (32x compression). More complex: requires codebook training, distance computed via lookup tables. Binary quantization: each dimension → 1 bit, using Hamming distance. 96x compression but significant recall loss, useful as a first-pass filter. Recommendation: start with SQ (int8), use PQ only if memory budget requires >4x compression.', tags: ['scalar-quantization', 'product-quantization', 'compression', 'memory'] },
  { id: 'ai-engineer-vector-db-l4-006', language: 'ai-engineer', level: 'level4', category: 'Vector Databases & Embeddings', subcategory: 'Filtering', question: 'Why is combining vector search with metadata filtering technically challenging and what approaches exist?', options: ['Pre-filtering (filter first, then search filtered subset) can miss relevant vectors if the filter is too restrictive and the ANN index doesn\'t support it natively. Post-filtering (search first, then filter results) wastes compute and may return fewer than k results. In-filter search (integrated filtering during graph/index traversal) is ideal but complex to implement. Qdrant, Weaviate, and Pinecone implement various hybrid approaches with different performance characteristics', 'Metadata filtering is trivially combined with vector search', 'Filtering is only needed for text metadata, not numerical attributes', 'Post-filtering always returns exactly k results'], correctAnswer: 0, explanation: 'The filter-search interaction problem: (1) Pre-filter then search: apply filter → search within filtered set. If using HNSW, this means traversing the graph but skipping filtered-out nodes, potentially getting stuck in disconnected subgraphs → poor recall. Works well with IVF (filter centroids/vectors in lists). (2) Post-filter: search top-k×multiplier → filter → return top-k. Wastes compute if filter is selective (99% filtered out). (3) Native filtered search: Qdrant uses filterable HNSW with payload indexes; Pinecone combines metadata index with vector index in a single query plan; Weaviate uses inverted index + HNSW integration. Performance depends heavily on filter selectivity — 1% selectivity vs 90% selectivity requires different strategies.', tags: ['filtered-search', 'metadata', 'pre-filter', 'post-filter'] },
  { id: 'ai-engineer-vector-db-l4-007', language: 'ai-engineer', level: 'level4', category: 'Vector Databases & Embeddings', subcategory: 'Late Interaction', question: 'What is ColBERT\'s late interaction mechanism and why does it outperform single-vector retrieval?', options: ['ColBERT is slower than cross-encoder models', 'ColBERT uses a single vector per document like standard bi-encoders', 'ColBERT encodes queries and documents into multiple token-level vectors (one per token). Relevance is computed as the sum of maximum similarity between each query token vector and all document token vectors (MaxSim). This late interaction captures fine-grained token-level matching while still allowing document vectors to be precomputed and indexed, achieving quality close to cross-encoders with efficiency close to bi-encoders', 'Late interaction produces a single relevance score without considering individual tokens'], correctAnswer: 2, explanation: 'ColBERT (Khattab & Zaharia 2020): query "what is attention?" → q1, q2, q3, q4 (token vectors). Document → d1, d2, ..., dN. Score = Σ_i max_j sim(qi, dj). Each query token finds its best-matching document token. This captures: (1) exact term matching (token-level), (2) semantic matching (contextualized embeddings), (3) partial matching (not all query terms need to match). Document vectors are precomputed and stored (ColBERTv2 uses residual compression: ~2 bytes per token). Index: for each document, store all token vectors in an ANN index. Query: for each query token, find nearest document tokens, aggregate by document. ColBERTv2 achieves near-cross-encoder quality with ~100x speedup.', tags: ['colbert', 'late-interaction', 'maxsim', 'multi-vector'] },
  { id: 'ai-engineer-vector-db-l4-008', language: 'ai-engineer', level: 'level4', category: 'Vector Databases & Embeddings', subcategory: 'Embedding Spaces', question: 'What is the "representation bottleneck" in single-vector document embeddings and how do multi-vector representations address it?', options: ['A fixed-dimensional vector (e.g., 768-d) cannot faithfully represent all the diverse topics and details in a long document — this is the representation bottleneck. Multi-vector approaches (ColBERT tokens, paragraph-level chunks, or learned multiple embeddings per document) preserve more information by using multiple vectors per document, with the trade-off of increased storage and more complex retrieval but significantly better recall for complex queries', 'Multi-vector representations require less storage than single vectors', 'A single vector can capture all information in any document', 'The representation bottleneck only affects documents longer than 10,000 words'], correctAnswer: 0, explanation: 'A 768-d vector has ~6KB of information — it cannot compress a 10-page document with multiple topics. Consequence: queries about specific details often fail because the document vector averages over all content. Solutions: (1) chunk document into passages, embed each separately (most common), (2) ColBERT: one vector per token, (3) Multi-vector models: learn 2-10 "aspect" embeddings per document, each capturing different topics, (4) Hypothetical document indexing: generate multiple hypothetical queries per document, embed those. Trade-off: N vectors per document = N× storage and N× index size. For 1B documents with 10 vectors each: 10B vectors to index. Production systems typically use chunking (5-20 chunks per document) as the practical middle ground.', tags: ['representation-bottleneck', 'multi-vector', 'chunking', 'document-embedding'] },
  { id: 'ai-engineer-vector-db-l4-009', language: 'ai-engineer', level: 'level4', category: 'Vector Databases & Embeddings', subcategory: 'Distance Metrics', question: 'When should you use cosine similarity vs inner product vs Euclidean distance for vector search?', options: ['The choice of distance metric has no impact on retrieval quality', 'Cosine similarity measures angle between vectors (ignores magnitude), ideal for normalized embeddings where direction encodes semantics. Inner product (dot product) considers both direction and magnitude, useful when vector magnitude is meaningful (e.g., represents document importance). Euclidean distance measures absolute difference, works for vectors where spatial positioning matters (e.g., word2vec). For normalized vectors, all three produce identical rankings since ||a-b||² = 2 - 2·cos(a,b)', 'Euclidean distance is always the best choice', 'All distance metrics produce identical rankings'], correctAnswer: 1, explanation: 'For L2-normalized embeddings (||v||=1): cosine = dot product, and L2² = 2(1-cosine), so all three metrics give identical rankings — choose any. For unnormalized embeddings: cosine ignores magnitude (a long and short vector pointing the same direction are identical), dot product rewards larger magnitudes (useful in MIPS — maximum inner product search, where magnitude encodes relevance strength), L2 measures geometric distance (useful for spatial embeddings). Most modern embedding models (OpenAI, Cohere, E5) output normalized vectors → cosine/dot product are equivalent. For CLIP, dot product is standard. For graph embeddings with meaningful magnitudes, inner product is preferred.', tags: ['distance-metrics', 'cosine-similarity', 'inner-product', 'euclidean'] },
  { id: 'ai-engineer-vector-db-l4-010', language: 'ai-engineer', level: 'level4', category: 'Vector Databases & Embeddings', subcategory: 'Sentence Embeddings', question: 'What is the contrastive fine-tuning approach (as in E5, BGE, GTE models) for creating high-quality text embeddings?', options: ['Modern embedding models use multi-stage training: (1) pre-training on massive weakly-supervised text pairs (title-body, query-passage from web data), (2) fine-tuning with contrastive loss on curated datasets with hard negatives (MS MARCO, NLI, etc.), and optionally (3) instruction-tuned embedding where the query is prefixed with task description. Hard negative mining and in-batch negatives are critical for learning fine-grained distinctions between semantically similar but non-relevant passages', 'Fine-tuning always degrades embedding quality', 'Embedding models only need to be trained on random text pairs', 'High-quality embeddings are produced by the base LLM without fine-tuning'], correctAnswer: 0, explanation: 'E5 (Wang et al. 2022), BGE (Xiao et al. 2023), GTE: Stage 1: pre-train on ~1B weakly-supervised pairs scraped from web (question→answer, title→abstract). This gives broad semantic understanding. Stage 2: fine-tune on ~1M curated pairs with hard negatives. Hard negatives are retrieved by a dense model and are challenging (same topic but different answer). InfoNCE loss with in-batch negatives + mined hard negatives. Stage 3 (optional): instruction tuning — prepend task description to query ("Retrieve passages that answer:"). This disambiguates between different retrieval intents (question→answer vs document→similar document). Result: embeddings that outperform OpenAI ada-002 at 1/10th the cost.', tags: ['embedding-models', 'contrastive-finetuning', 'hard-negatives', 'e5'] },
  { id: 'ai-engineer-vector-db-l4-011', language: 'ai-engineer', level: 'level4', category: 'Vector Databases & Embeddings', subcategory: 'Disk-Based Index', question: 'How does DiskANN enable billion-scale vector search with limited memory by leveraging SSDs?', options: ['SSD-based indices cannot achieve high recall', 'DiskANN is slower than brute-force search', 'DiskANN requires all vectors to fit in RAM', 'DiskANN builds a Vamana graph index (similar to HNSW) on SSD, keeping only compressed vectors (PQ codes) in memory for distance estimation during graph traversal. Full-precision vectors are loaded from SSD only for final candidate reranking. The graph traversal pattern is optimized for sequential SSD reads by caching frequently-visited nodes. This enables searching 1B+ vectors with only ~64GB RAM instead of ~500GB'], correctAnswer: 3, explanation: 'DiskANN (Subramanya et al. 2019): (1) Build Vamana graph (degree-bounded, navigable, like HNSW but single-layer for SSD-friendliness), (2) Store graph + PQ codes in RAM (~32 bytes/vector × 1B = 32GB), full vectors on SSD (~3KB/vector × 1B = 3TB), (3) Search: traverse graph using PQ distances for candidate selection (in-memory), read full vectors from SSD for top candidates to compute exact distances (reranking). Key optimization: beam search gathers many candidates before issuing a single batched SSD read (sequential I/O, ~500μs per batch). Achieves >95% recall@10 at ~5ms latency on 1B vectors with 64GB RAM + NVMe SSD.', tags: ['diskann', 'ssd-index', 'billion-scale', 'vamana'] },
  { id: 'ai-engineer-vector-db-l4-012', language: 'ai-engineer', level: 'level4', category: 'Vector Databases & Embeddings', subcategory: 'Reranking', question: 'What is the computational trade-off between bi-encoders and cross-encoders for retrieval, and why is a two-stage pipeline standard?', options: ['The two-stage pipeline doubles the total latency', 'Bi-encoders provide higher quality than cross-encoders', 'Cross-encoders are always faster than bi-encoders', 'Bi-encoders embed query and document independently, enabling precomputation and ANN search over millions of documents in milliseconds. Cross-encoders process (query, document) pairs jointly through a transformer, computing O(n²) attention over concatenated tokens — much more accurate but O(N) in documents. The standard two-stage pipeline uses a bi-encoder for fast recall (top-100), then a cross-encoder for precise reranking (top-10), combining efficiency with quality'], correctAnswer: 3, explanation: 'Bi-encoder: encode query once (10ms) + ANN search over precomputed embeddings (5ms) = 15ms for millions of documents. Quality: limited by fixed-size embedding bottleneck. Cross-encoder: concatenate (query, doc_i) → BERT → score. 100ms per pair × 1M documents = infeasible. Quality: excellent, full token-level interaction between query and document. Two-stage: (1) bi-encoder retrieves top-100 in 15ms, (2) cross-encoder scores 100 pairs in 200ms, (3) return top-10. Total: 215ms with near-cross-encoder quality. This is the standard in Cohere Rerank, MS MARCO leaderboard systems, and production RAG pipelines.', tags: ['bi-encoder', 'cross-encoder', 'reranking', 'two-stage-retrieval'] },
  { id: 'ai-engineer-vector-db-l4-013', language: 'ai-engineer', level: 'level4', category: 'Vector Databases & Embeddings', subcategory: 'Index Updates', question: 'What challenges arise when updating vector indices in production and how do databases handle incremental updates?', options: ['Vector indices can be updated instantly with no performance impact', 'HNSW supports incremental inserts but not efficient deletes (deleted vectors leave "holes" in the graph degrading quality over time). IVF indices need periodic re-clustering as data distribution shifts. Production databases use write-ahead logs, background compaction (merge small segments into optimized larger ones), and tombstone markers for deletes with periodic rebuild. Milvus and Qdrant use segment-based architectures with sealed (read-optimized) and growing (write-optimized) segments', 'Deleting vectors from an index has no performance impact', 'All vector indices must be rebuilt from scratch for any update'], correctAnswer: 1, explanation: 'Challenges: (1) HNSW inserts: add node, connect to M nearest — works but graph quality degrades vs bulk-built graph, (2) HNSW deletes: removing a node can disconnect the graph; typically use soft delete (tombstone) + periodic rebuild, (3) IVF: inserting into fixed cells is fine, but if data distribution shifts, cells become imbalanced → poor recall. Production patterns: Milvus uses sealed segments (immutable, optimized index) + growing segment (append-only, no index). Queries search both. Background process seals and indexes growing segments. Periodic compaction merges small segments. This LSM-tree-inspired architecture handles continuous writes while maintaining search quality.', tags: ['index-updates', 'incremental', 'compaction', 'production'] },
  { id: 'ai-engineer-vector-db-l4-014', language: 'ai-engineer', level: 'level4', category: 'Vector Databases & Embeddings', subcategory: 'Embedding Drift', question: 'What is embedding drift and how does it affect retrieval systems when the embedding model is updated?', options: ['Embedding models always produce the same vectors across versions', 'Only queries need re-embedding when the model changes', 'When the embedding model is updated (new version, fine-tuned), new query embeddings are incompatible with previously stored document embeddings because the vector spaces are different. This requires re-embedding all documents — expensive for large corpora. Backward-compatible training (constraining new embeddings to be close to old ones) and model versioned indexing (maintaining separate indices per model version during migration) address this', 'Updating the embedding model has no effect on existing embeddings'], correctAnswer: 2, explanation: 'Problem: 100M documents embedded with model_v1 → update to model_v2 → queries encoded with v2 are in a different space than documents encoded with v1 → retrieval quality collapses. Solutions: (1) Full re-embedding: re-encode all documents with v2 (expensive: 100M × $0.001 = $100K + compute time), (2) Backward-compatible training: add a contrastive loss term that keeps v2 embeddings close to v1 embeddings for the same text, enabling gradual migration, (3) Dual-index: maintain v1 and v2 indices, query both during transition, (4) Adapter: train a lightweight linear transform from v1 space to v2 space. Production: most companies maintain versioned indices and do rolling re-embedding as a background job.', tags: ['embedding-drift', 'model-update', 'backward-compatible', 're-embedding'] },
  { id: 'ai-engineer-vector-db-l4-015', language: 'ai-engineer', level: 'level4', category: 'Vector Databases & Embeddings', subcategory: 'Multi-Tenancy', question: 'How do vector databases implement multi-tenancy for SaaS applications where each customer has separate data?', options: ['Vector databases do not support multi-tenancy', 'Multi-tenancy approaches: (1) partition-based: store tenant_id as metadata, filter during search (simplest, shared index), (2) namespace/collection-per-tenant: separate index per tenant (better isolation, more resource overhead), (3) cluster-per-tenant: full isolation (expensive, best for large tenants). Trade-offs involve search quality (filtering reduces recall), resource efficiency (shared vs dedicated), data isolation requirements (compliance), and query latency (filtering adds overhead)', 'Each customer requires a separate database cluster', 'Multi-tenancy has no impact on search performance'], correctAnswer: 1, explanation: 'For a SaaS RAG application with 10K customers: (1) Shared index + metadata filter: one large index, each vector has tenant_id. Pro: efficient resource use. Con: filter during search reduces recall (see filtering challenges), noisy neighbor risk. (2) Collection per tenant: Qdrant/Milvus create separate collections. Pro: clean isolation, no filter overhead. Con: 10K small indices are less memory-efficient than one large one, cold start for rarely-queried tenants. (3) Pinecone namespaces: lightweight separation within a single index. Recommendation: metadata filtering for <1000 tenants, namespace/collection for 1000-10K, dedicated clusters for enterprise tenants with SLA requirements.', tags: ['multi-tenancy', 'saas', 'data-isolation', 'partitioning'] },
  { id: 'ai-engineer-vector-db-l4-016', language: 'ai-engineer', level: 'level4', category: 'Vector Databases & Embeddings', subcategory: 'Sparse Embeddings', question: 'What are learned sparse embeddings (SPLADE) and why do they outperform BM25?', options: ['Learned sparse embeddings require dense vector indices', 'BM25 always outperforms learned sparse methods', 'SPLADE uses traditional TF-IDF weighting', 'SPLADE uses a pretrained language model (BERT) to predict sparse term weights for each token in the vocabulary, enabling semantic term expansion. A query about "automobile" activates not just "automobile" but also "car", "vehicle" with learned weights. Combined with FLOPS regularization to maintain sparsity, SPLADE achieves BM25-like efficiency with neural-quality semantic matching in an inverted index format'], correctAnswer: 3, explanation: 'SPLADE (Formal et al. 2021): input text → BERT → log(1 + ReLU(MLM_head)) → sparse vector over vocabulary. Each dimension represents a vocabulary term\'s importance. "The car is fast" might produce: {car: 2.1, automobile: 1.3, vehicle: 0.9, fast: 1.8, speed: 0.7, ...}. FLOPS regularizer encourages sparsity (~100 non-zero terms per document). Stored in standard inverted indices (Lucene/Elasticsearch). Benefits over BM25: (1) semantic expansion (synonyms activated), (2) learned term weights > TF-IDF, (3) integrates contextual understanding. Used as the sparse component in hybrid search, replacing BM25 with better quality and the same infrastructure.', tags: ['splade', 'learned-sparse', 'term-expansion', 'inverted-index'] },
  { id: 'ai-engineer-vector-db-l4-017', language: 'ai-engineer', level: 'level4', category: 'Vector Databases & Embeddings', subcategory: 'Benchmarking', question: 'What metrics should be used to benchmark vector database performance and what are common benchmarking pitfalls?', options: ['Only recall@10 matters for vector database evaluation', 'Latency and recall are independent metrics that can be optimized separately', 'Vector database benchmarks are always fair and comparable', 'Key metrics: recall@k (search quality), queries per second (throughput), p50/p99 latency (tail latency matters for SLA), index build time, memory usage per vector, and these should be measured across different dataset sizes and filter selectivities. Common pitfalls: benchmarking with unrealistically small datasets, not measuring under concurrent load, ignoring index build time, and not accounting for the recall-speed-memory three-way trade-off'], correctAnswer: 3, explanation: 'Benchmarking properly: (1) Recall@k at different throughput levels (Pareto curve, not single point), (2) Measure p99 latency, not just average (tail latency determines SLA), (3) Test with realistic data sizes (ANN-Benchmarks uses 1M vectors but production may need 100M+), (4) Include concurrent load (single-query latency ≠ production latency), (5) Measure with filters (filtered search is often 2-10x slower), (6) Report memory per vector (HNSW uses ~1KB/vector overhead vs IVF-PQ ~100 bytes). Pitfalls: comparing recall at different latency budgets, benchmarking without GPU warmup, ignoring index build time (HNSW can take hours for 100M vectors), and not testing insert/delete performance alongside search.', tags: ['benchmarking', 'recall', 'latency', 'throughput'] },
  { id: 'ai-engineer-vector-db-l4-018', language: 'ai-engineer', level: 'level4', category: 'Vector Databases & Embeddings', subcategory: 'Embedding Adaptation', question: 'When should you fine-tune an embedding model versus using a general-purpose model like OpenAI text-embedding-3?', options: ['General-purpose embedding models are always sufficient', 'Fine-tuning requires at least 1 million training pairs', 'Fine-tune when: (1) your domain has specialized vocabulary not in the pretraining data (legal, medical, code), (2) retrieval quality on your specific query-document pairs is below threshold, (3) you need to optimize for a specific retrieval pattern (question→answer vs document→similar document). Use general-purpose when: data is insufficient for fine-tuning (<1K pairs), domain is well-covered by web text, or rapid prototyping. Fine-tuning on as few as 1K-10K high-quality pairs can improve recall by 5-15% on domain-specific tasks', 'Fine-tuning always degrades embedding quality'], correctAnswer: 2, explanation: 'General models (OpenAI, Cohere, Voyage) are trained on diverse web data and work well for general domains. But: (1) medical queries "STEMI management protocol" may not match relevant cardiology documents because the model hasn\'t seen enough medical text, (2) code retrieval requires understanding code semantics, (3) internal documentation uses company-specific terminology. Fine-tuning approaches: (a) contrastive fine-tuning on (query, relevant_doc, hard_negative) triplets, (b) PEFT/LoRA for efficient adaptation, (c) Matryoshka fine-tuning to maintain multi-resolution properties. Data: mine hard negatives from the general model\'s errors. As few as 1K high-quality pairs can significantly improve domain retrieval.', tags: ['embedding-finetuning', 'domain-adaptation', 'retrieval-quality', 'contrastive-learning'] },
  { id: 'ai-engineer-vector-db-l4-019', language: 'ai-engineer', level: 'level4', category: 'Vector Databases & Embeddings', subcategory: 'Multimodal Embeddings', question: 'How do multimodal embedding models like CLIP enable cross-modal retrieval?', options: ['CLIP trains image and text encoders jointly with contrastive loss so that matching image-text pairs have high similarity in a shared embedding space. This enables: text-to-image search (embed text query, find nearest image embeddings), image-to-text search, and zero-shot classification. The key is that both modalities map to the same geometric space where semantic similarity is preserved across modalities', 'Cross-modal retrieval requires explicit image-text pair lookups', 'Multimodal models use separate embedding spaces for each modality', 'CLIP can only compare images with images, not images with text'], correctAnswer: 0, explanation: 'CLIP (Radford et al. 2021): image encoder (ViT) + text encoder (transformer) trained to maximize cosine similarity for matched (image, text) pairs and minimize for unmatched. Shared 512/768-d space. This enables: (1) text→image: embed "a red sports car" → find nearest images, (2) image→text: embed a photo → find nearest text descriptions, (3) zero-shot classification: embed class descriptions as text → classify image by nearest text embedding. For vector databases: index image embeddings, query with text embeddings (or vice versa). Extensions: ImageBind extends to 6 modalities (image, text, audio, depth, thermal, IMU) in a single shared space.', tags: ['clip', 'multimodal-embeddings', 'cross-modal', 'shared-space'] },
  { id: 'ai-engineer-vector-db-l4-020', language: 'ai-engineer', level: 'level4', category: 'Vector Databases & Embeddings', subcategory: 'Dimensionality', question: 'What is the impact of embedding dimensionality on retrieval quality, speed, and storage?', options: ['Embedding dimensionality has no impact on search performance', '64-dimensional embeddings are always sufficient', 'Higher dimensions (1024-4096) can represent more nuanced semantic relationships but increase storage (4× for 4096 vs 1024), slow down distance computation, and may degrade with noise in sparse data (curse of dimensionality). Lower dimensions (256-384) are faster and cheaper but may lose fine-grained distinctions. Matryoshka embeddings allow choosing dimensionality at query time. Empirically, 768-1024 dimensions offer the best quality-efficiency trade-off for most text retrieval tasks', 'Higher dimensionality always improves retrieval quality'], correctAnswer: 2, explanation: 'Dimensionality trade-offs: Storage: 1B vectors × 768 × 4 bytes = 3TB vs 1B × 256 × 4 = 1TB. Speed: distance computation is O(d), ANN index build/search also scales with d. Quality: OpenAI text-embedding-3: 256-d achieves 88% recall, 1536-d achieves 92%, 3072-d achieves 92.5% — diminishing returns past 1024-1536. The curse of dimensionality: in very high dimensions, distances become increasingly uniform (all pairs similarly distant), degrading nearest-neighbor quality. PCA or Matryoshka truncation can reduce dimensions post-hoc with minimal quality loss. Practical: 768-d (BERT-base sized) is the sweet spot for most applications.', tags: ['dimensionality', 'storage', 'quality-tradeoff', 'curse-of-dimensionality'] },
  { id: 'ai-engineer-vector-db-l4-021', language: 'ai-engineer', level: 'level4', category: 'Vector Databases & Embeddings', subcategory: 'Triplet Loss', question: 'What is the triplet margin loss and why has it largely been replaced by InfoNCE for embedding training?', options: ['InfoNCE cannot be used for embedding training', 'Triplet loss always outperforms InfoNCE', 'Triplet loss trains on (anchor, positive, negative) triplets with L = max(0, d(a,p) - d(a,n) + margin). It requires careful mining of hard triplets and only uses one negative per update. InfoNCE uses all in-batch examples as negatives (B-1 negatives per query), providing a much richer gradient signal per batch. InfoNCE also naturally produces well-calibrated similarity scores, while triplet loss only enforces a relative ordering with an arbitrary margin', 'Triplet loss and InfoNCE are identical'], correctAnswer: 2, explanation: 'Triplet loss: L = max(0, ||a-p||² - ||a-n||² + margin). Problems: (1) only 1 negative per triplet — inefficient use of batch, (2) requires hard negative mining (semi-hard, hard, or curriculum) — training is sensitive to mining strategy, (3) margin is a hyperparameter that is hard to tune, (4) many triplets are "easy" (contribute zero loss), wasting compute. InfoNCE: uses entire batch as negatives (B=4096 → 4095 negatives per query), temperature replaces margin (easier to tune), cross-entropy loss is well-studied. Multiple Negatives Ranking Loss (MNRL) is InfoNCE for pairs. Most modern embedding models (E5, GTE, Cohere) use InfoNCE-family losses.', tags: ['triplet-loss', 'infonce', 'contrastive-learning', 'embedding-training'] },
  { id: 'ai-engineer-vector-db-l4-022', language: 'ai-engineer', level: 'level4', category: 'Vector Databases & Embeddings', subcategory: 'Graph-Based', question: 'What is the theoretical basis for the "small-world" property in HNSW and how does it guarantee efficient search?', options: ['Small-world networks have high clustering (nearby nodes are well-connected) and short average path lengths (any two nodes are connected by few hops). HNSW constructs such networks by connecting each node to its nearest neighbors (high clustering) across multiple layers (short paths via hierarchy). With logarithmic layer structure, the expected number of hops to reach any node is O(log N), providing polylogarithmic search complexity with high probability', 'Small-world properties only exist in random graphs', 'HNSW has no theoretical guarantees', 'HNSW search is O(N) in the worst case with no improvements over brute force'], correctAnswer: 0, explanation: 'Navigable small-world (NSW) theory: a graph with both local structure (greedy routing works locally) and long-range connections (skip across the graph) enables efficient greedy search. HNSW adds hierarchy: layer L has ~N/e^L nodes. Search: start at top layer (few nodes, long-range connections) → greedily descend → bottom layer (all nodes, local connections). At each layer, greedy search follows the nearest neighbor chain. Expected hops per layer: O(1/ln(M)) where M is the degree. Total layers: O(log N). Total hops: O(log N / ln M). This gives practical sub-millisecond search on millions of vectors.', tags: ['small-world', 'hnsw-theory', 'graph-navigation', 'logarithmic'] },
  { id: 'ai-engineer-vector-db-l4-023', language: 'ai-engineer', level: 'level4', category: 'Vector Databases & Embeddings', subcategory: 'Production', question: 'What are the key considerations when choosing between Pinecone, Weaviate, Qdrant, Milvus, and pgvector for production?', options: ['Pinecone: fully managed, no infrastructure management, but cloud-only and vendor lock-in. Weaviate: modular, supports multiple vectorizers, GraphQL API. Qdrant: high-performance Rust-based, excellent filtering, good for self-hosted. Milvus: designed for billion-scale, distributed architecture, but complex to operate. pgvector: PostgreSQL extension, simplest for small-medium scale if you already use Postgres, but limited index options and performance at scale. Choice depends on scale, team expertise, cloud/on-prem requirements, and filtering needs', 'pgvector is always the best choice regardless of scale', 'All vector databases are identical in capability and performance', 'Managed databases are always more expensive than self-hosted'], correctAnswer: 0, explanation: 'Decision framework: Scale <1M vectors + existing Postgres → pgvector (simplest, no new infrastructure). Scale 1-100M + managed preference → Pinecone (zero ops) or Weaviate Cloud. Scale 1-100M + self-hosted → Qdrant (excellent performance/simplicity ratio) or Weaviate. Scale >100M → Milvus (distributed, segment-based) or Pinecone (managed scaling). Complex filtering → Qdrant (payload indexes) or Weaviate (inverted index integration). Multimodal → Weaviate (built-in vectorizer modules). Key metrics to evaluate: recall@10 at target latency, filtered search performance, operational complexity, cost per query, and availability/consistency guarantees.', tags: ['database-comparison', 'pinecone', 'qdrant', 'milvus'] },
  { id: 'ai-engineer-vector-db-l4-024', language: 'ai-engineer', level: 'level4', category: 'Vector Databases & Embeddings', subcategory: 'Knowledge Distillation', question: 'How can cross-encoder knowledge be distilled into a bi-encoder for faster retrieval?', options: ['Cross-encoder knowledge cannot be transferred to bi-encoders', 'Bi-encoders always match cross-encoder quality without distillation', 'Train the bi-encoder to produce similarity scores that match the cross-encoder\'s scores on the same (query, document) pairs. Use the cross-encoder to score a large set of query-document pairs (including hard negatives), then train the bi-encoder with MSE or margin-based loss against these soft labels. This produces a bi-encoder that captures much of the cross-encoder\'s ranking quality while retaining the efficiency of independent encoding and ANN search', 'Distillation requires retraining the cross-encoder'], correctAnswer: 2, explanation: 'Cross-encoder distillation for bi-encoders (Hofstätter et al. 2020): (1) use cross-encoder to score (query, doc) pairs from BM25 top-100 results, (2) train bi-encoder with: L = MSE(bi_score(q,d), ce_score(q,d)) or margin loss using CE rankings. The bi-encoder learns to approximate cross-encoder rankings. This is more effective than training on binary labels because soft scores from the cross-encoder encode fine-grained relevance differences (doc A is slightly more relevant than doc B). GPL (Generative Pseudo Labeling): generates queries for documents, uses cross-encoder to label, then distills — enabling domain adaptation without any labeled data.', tags: ['distillation', 'cross-encoder', 'bi-encoder', 'soft-labels'] },
  { id: 'ai-engineer-vector-db-l4-025', language: 'ai-engineer', level: 'level4', category: 'Vector Databases & Embeddings', subcategory: 'Evaluation', question: 'What is NDCG@k and why is it preferred over recall@k for evaluating retrieval with graded relevance?', options: ['Recall@k always provides more information than NDCG@k', 'NDCG@k can only be computed with binary relevance labels', 'NDCG and recall measure the same thing', 'NDCG@k (Normalized Discounted Cumulative Gain) accounts for both relevance grades and ranking position: highly relevant results at the top contribute more than marginally relevant results lower in the ranking. Recall@k only measures whether relevant documents appear anywhere in the top k, ignoring their position and relevance degree. For RAG systems where the top-1 result matters much more than top-10, NDCG better reflects actual utility'], correctAnswer: 3, explanation: 'NDCG@k = DCG@k / IDCG@k where DCG@k = Σ (2^rel_i - 1) / log2(i+1). The denominator discounts lower-ranked results (position 1 has weight 1, position 10 has weight 1/log2(11) ≈ 0.29). Graded relevance: "highly relevant" (3) at position 1 contributes much more than "partially relevant" (1) at position 5. Recall@k treats all relevant documents equally and ignores position. For RAG: the model reads top-3 context passages — having the best passage at position 1 vs position 10 makes a huge quality difference. MRR (Mean Reciprocal Rank) is simpler: 1/rank of first relevant result. MAP averages precision at each relevant position.', tags: ['ndcg', 'evaluation', 'graded-relevance', 'ranking-metrics'] },
  { id: 'ai-engineer-vector-db-l4-026', language: 'ai-engineer', level: 'level4', category: 'Vector Databases & Embeddings', subcategory: 'GPU Acceleration', question: 'How does GPU-accelerated vector search (FAISS GPU, cuVS/RAFT) compare to CPU-based search?', options: ['GPUs cannot accelerate vector search operations', 'GPU vector search requires specialized vector databases', 'GPU search is always faster than CPU search for all index types', 'GPUs excel at the massively parallel distance computations in brute-force and IVF search: computing distances between a query and millions of vectors simultaneously. FAISS GPU achieves 10-100x throughput over CPU for brute-force and IVF-PQ search. However, graph-based indices (HNSW) are harder to parallelize on GPU due to irregular memory access patterns. GPU search is most beneficial for batch queries and large-scale IVF indices, while CPU HNSW may win for single low-latency queries'], correctAnswer: 3, explanation: 'GPU advantages: (1) Brute-force: computing dot product of query with 1M vectors is a single matrix multiplication — perfectly parallelizable on GPU. FAISS GPU flat: ~1ms for 1M × 768-d vectors (vs ~100ms CPU). (2) IVF: distance to centroids + scanning inverted lists = parallel reductions. FAISS GPU IVF-PQ: ~0.5ms for 100M vectors. GPU challenges: (1) HNSW traversal has irregular memory access (follow edges → read neighbor data → decide next edge) — poor GPU utilization due to warp divergence. (2) GPU memory limits index size (80GB H100 vs 2TB CPU RAM). (3) CPU can handle concurrent queries via threads; GPU is batch-oriented. cuVS (NVIDIA): optimized GPU implementations of IVF-PQ, CAGRA (GPU graph index), achieving near-HNSW recall with GPU throughput.', tags: ['gpu-search', 'faiss-gpu', 'cuvs', 'parallel-computation'] },
  { id: 'ai-engineer-vector-db-l4-027', language: 'ai-engineer', level: 'level4', category: 'Vector Databases & Embeddings', subcategory: 'Retrieval Augmented', question: 'What is the "parent document retriever" pattern and when should it be used in RAG?', options: ['Small chunks always provide sufficient context for the LLM', 'Parent document retrieval always returns the entire document', 'Parent document retrieval retrieves the same chunk used for embedding', 'Parent document retrieval embeds small chunks for precise retrieval matching but returns the larger parent chunk (or full document section) as context to the LLM. This addresses the trade-off where small chunks improve retrieval precision but lack sufficient context for generation. The LLM receives more surrounding context than what was matched, reducing the chance of missing relevant information adjacent to the matched passage'], correctAnswer: 3, explanation: 'The chunking dilemma: small chunks (128 tokens) → precise embedding match but the LLM may lack context ("the drug was administered" — which drug?). Large chunks (1024 tokens) → good context but embedding represents mixed topics → imprecise retrieval. Parent document pattern: (1) chunk into small pieces (child chunks) for embedding, (2) maintain mapping child → parent (larger section or full document), (3) retrieve by matching child chunks, (4) return parent chunks to the LLM. LangChain\'s ParentDocumentRetriever and LlamaIndex\'s auto-merging retriever implement this. Deduplication needed when multiple child chunks from the same parent match.', tags: ['parent-document', 'chunking', 'rag-pattern', 'context-window'] },
  { id: 'ai-engineer-vector-db-l4-028', language: 'ai-engineer', level: 'level4', category: 'Vector Databases & Embeddings', subcategory: 'Consistency', question: 'What consistency guarantees do vector databases provide and why does eventual consistency affect search results?', options: ['Eventual consistency means data is eventually deleted', 'Most distributed vector databases provide eventual consistency: a newly inserted or updated vector may not appear in search results immediately. This means a user might upload a document and not find it via search for seconds to minutes. Strong consistency (every write immediately visible) requires synchronous index updates which are expensive for large indices. The choice between eventual and strong consistency affects application design — upsert-then-search patterns may need explicit wait or read-your-writes guarantees', 'Consistency has no impact on search results', 'All vector databases provide strong consistency'], correctAnswer: 1, explanation: 'Vector index update is expensive: inserting into HNSW requires finding neighbors and updating edges (~milliseconds per vector). For throughput, databases batch updates: Pinecone provides freshness SLA of ~seconds, Milvus/Qdrant segment-based approaches have write-ahead log → segment seal → index build pipeline. Implications: (1) upload document → immediately search → may not find it (eventual consistency), (2) delete document → may still appear in results briefly. Strong consistency options: pgvector with synchronous inserts (but slower throughput), or application-level: track pending vectors, supplement search with recency filter. Design pattern: return "indexing in progress" status for recently uploaded documents.', tags: ['consistency', 'eventual-consistency', 'freshness', 'distributed'] },
  { id: 'ai-engineer-vector-db-l4-029', language: 'ai-engineer', level: 'level4', category: 'Vector Databases & Embeddings', subcategory: 'Negative Sampling', question: 'What is the role of in-batch negatives versus hard negatives in contrastive embedding training?', options: ['In-batch negatives treat all other positives in the mini-batch as negatives for each query — free, diverse, but mostly "easy" negatives. Hard negatives are specifically mined examples that are similar to the query but not relevant — these provide the most learning signal but can be noisy or false negatives. Optimal training combines both: in-batch negatives provide breadth while 1-3 hard negatives per query provide depth. Hard negatives should be refreshed periodically as the model improves', 'In-batch and hard negatives serve the same purpose', 'Only hard negatives are useful for training', 'In-batch negatives require additional computation beyond the forward pass'], correctAnswer: 0, explanation: 'In-batch negatives: batch of (q1,d1), (q2,d2), ..., (qB,dB). For q1: positives = {d1}, negatives = {d2,...,dB}. Free (no extra computation), but random — most are easy (topically unrelated to q1). Hard negatives: for q1, mine {d_hard} = documents about the same topic but not answering q1. These force the model to learn fine-grained distinctions. Mining methods: BM25 top-k (lexical similarity but not semantic), dense retriever top-k from current model (most challenging), cross-encoder filtered (remove false negatives). Schedule: start with easy negatives (in-batch only), gradually add harder negatives as the model improves. ANCE: refreshes hard negatives every few epochs from the updated model.', tags: ['in-batch-negatives', 'hard-negatives', 'contrastive', 'mining'] },
  { id: 'ai-engineer-vector-db-l4-030', language: 'ai-engineer', level: 'level4', category: 'Vector Databases & Embeddings', subcategory: 'Streaming Updates', question: 'How do feature embedding tables handle real-time updates for recommendation systems?', options: ['Embedding tables are static and never updated', 'User and item embeddings are always computed in real-time', 'Embedding updates have no impact on recommendation quality', 'Recommendation systems maintain embedding tables for users and items that need frequent updates as new interactions occur. Approaches: (1) periodic full recomputation (simple but stale), (2) incremental updates using lightweight models that adjust embeddings based on new interactions, (3) two-tower retrieval where user embeddings are computed at request time from features (always fresh) while item embeddings are precomputed and cached. The choice depends on update frequency requirements and computational budget'], correctAnswer: 3, explanation: 'Recommendation embedding challenge: user preferences change (watched a new movie), items change (new products added). Options: (1) Full retrain: batch job every 24h → embeddings are up to 24h stale. (2) Incremental: on new interaction, adjust user embedding via a lightweight model (e.g., moving average with new item embedding). (3) Two-tower at serving: user tower computes embedding from recent features (last 50 interactions) at request time → always fresh. Item embeddings precomputed and indexed. (4) Streaming: Kafka pipeline updates embeddings as events arrive, writes to online store. Production systems often combine: user embeddings fresh at request time, item embeddings batch-updated hourly, with a real-time boosting layer for very recent items.', tags: ['streaming-updates', 'recommendation', 'embedding-tables', 'two-tower'] },
  { id: 'ai-engineer-vector-db-l4-031', language: 'ai-engineer', level: 'level4', category: 'Vector Databases & Embeddings', subcategory: 'Alignment', question: 'What is representation alignment and uniformity in embedding spaces, and why do both matter?', options: ['Alignment and uniformity are always in conflict', 'Uniformity means all embeddings should be identical', 'Alignment measures how close positive pairs are in the embedding space (similar items should have similar embeddings). Uniformity measures how evenly distributed embeddings are on the hypersphere (they should utilize the full space, not cluster in a narrow cone). Both are necessary: perfect alignment with poor uniformity means all embeddings collapse to a single point; perfect uniformity with poor alignment means random representations. Good embeddings optimize both simultaneously', 'Only alignment matters for embedding quality'], correctAnswer: 2, explanation: 'Wang & Isola (2020): L_align = E[||f(x) - f(x+)||²] (positive pairs should be close), L_uniform = log E[e^{-2||f(x) - f(y)||²}] (all pairs should be spread out). Contrastive loss implicitly optimizes both: the numerator maximizes agreement of positives (alignment), the denominator pushes negatives apart (uniformity). The anisotropy problem (all embeddings in a narrow cone) is a uniformity failure. SimCSE and other methods explicitly monitor both metrics. Temperature in InfoNCE controls the balance: low τ emphasizes hard negatives (more uniformity pressure), high τ treats negatives more equally (more alignment focus).', tags: ['alignment', 'uniformity', 'embedding-quality', 'contrastive-learning'] },
  { id: 'ai-engineer-vector-db-l4-032', language: 'ai-engineer', level: 'level4', category: 'Vector Databases & Embeddings', subcategory: 'Approximate Methods', question: 'What is Locality-Sensitive Hashing (LSH) and why has it been largely replaced by graph-based methods for ANN search?', options: ['LSH is the most efficient ANN method available', 'LSH hashes vectors so that similar vectors have high collision probability, enabling sub-linear search by only comparing vectors in the same hash buckets. However, it requires many hash tables for high recall (memory-intensive), has poor recall-speed trade-offs compared to graph methods, and its theoretical guarantees (c-approximate) are loose. HNSW and IVF-PQ achieve better recall at lower latency and memory, making LSH largely obsolete for dense vector search in practice', 'Graph-based methods have worse theoretical guarantees than LSH', 'LSH provides exact nearest neighbor results'], correctAnswer: 1, explanation: 'LSH for cosine: random hyperplane hashing. Hash each vector with L hash functions of K bits each → L hash tables. Query: look up same hash buckets, compare candidates. For high recall: need many tables (L=100+), each storing all vectors → 100× memory. Recall@10 vs latency: HNSW achieves 99% recall at 1ms while LSH might need 10ms for 95% recall on the same dataset. LSH\'s advantage: theoretical guarantees (c-approximate NN in sub-linear time). But in practice: HNSW/IVF-PQ dominate ANN benchmarks (ann-benchmarks.com). LSH remains useful for: (1) streaming data (easy to update hash tables), (2) exact near-duplicate detection (high precision at low cost), (3) specific distance metrics (MinHash for Jaccard similarity).', tags: ['lsh', 'locality-sensitive-hashing', 'hnsw-comparison', 'ann-methods'] },
  { id: 'ai-engineer-vector-db-l4-033', language: 'ai-engineer', level: 'level4', category: 'Vector Databases & Embeddings', subcategory: 'Scalability', question: 'How do distributed vector databases shard data across nodes while maintaining search quality?', options: ['Sharding eliminates the need for ANN indices', 'Distributed search always has the same recall as single-node search', 'Distributed vector databases partition vectors across shards using either random assignment or hash-based partitioning. Each query is broadcast to all shards (scatter), each shard returns its local top-k results, and a coordinator merges results (gather). The challenge: local top-k from each shard may not include the global top-k. Solutions include: over-fetching (request top-k×factor per shard), learned routing (predict which shards contain relevant vectors), and balanced partitioning to maintain recall across shards', 'Distributed vector search simply searches each shard independently'], correctAnswer: 2, explanation: 'Scatter-gather approach: N shards, each receives query → returns local top-k → coordinator merges N×k candidates → return global top-k. Recall concern: if the global top-1 result is on shard 3, it must be in shard 3\'s local top-k to be found. For IVF: partition cells across shards — nprobe determines which shards to query (not all). For HNSW: each shard has a complete HNSW graph on its subset. Balanced partitioning matters: if one shard has 2x more vectors, its local top-k is less likely to contain the global top-k. Milvus uses segment-based distribution; Pinecone and Qdrant use replica sets for high availability. Replication factor determines fault tolerance vs cost.', tags: ['distributed-search', 'sharding', 'scatter-gather', 'scalability'] },
];

export default questions;
